/**
 * RoadTwin AI — Checkpoint 11
 * Centralized Typed API Client for Production System, Observability & Demo Controller
 */

import {
  HealthResponse,
  SystemStatusResponse,
  SystemReadinessResponse,
  SystemDiagnosticsResponse,
  DigitalTwinStateResponse,
  SingleSegmentResponse,
  AlertListResponse,
  VMSResponse,
  PatrolResponse,
  TimelineResponse,
  DemoStepResponse,
  DemoResetResponse,
  IncidentSimulationResponse,
  DiversionRouteResponse,
  EmergencyDispatchResponse,
  ResetSimulationResponse,
  IncidentType,
  SeverityType,
  OperationalMode,
} from './types';

const BASE_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';

class ApiClient {
  private baseUrl: string;

  constructor(baseUrl: string) {
    this.baseUrl = baseUrl;
  }

  private async fetchWithTimeout<T>(endpoint: string, options: RequestInit = {}, timeoutMs: number = 10000): Promise<T> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);

    try {
      const res = await fetch(`${this.baseUrl}${endpoint}`, {
        ...options,
        signal: controller.signal,
        headers: {
          'Content-Type': 'application/json',
          ...options.headers,
        },
      });

      if (!res.ok) {
        const errorBody = await res.text().catch(() => '');
        throw new Error(`HTTP ${res.status} ${res.statusText}: ${errorBody}`);
      }

      const data = await res.json();
      return data as T;
    } catch (err: any) {
      if (err.name === 'AbortError') {
        throw new Error(`API Request Timeout (${timeoutMs}ms) on ${endpoint}`);
      }
      throw err;
    } finally {
      clearTimeout(timer);
    }
  }

  /**
   * Health check endpoint: GET /health
   */
  async getHealth(): Promise<HealthResponse> {
    return this.fetchWithTimeout<HealthResponse>('/health');
  }

  /**
   * Comprehensive system status: GET /api/v1/system/status
   */
  async getSystemStatus(): Promise<SystemStatusResponse> {
    return this.fetchWithTimeout<SystemStatusResponse>('/api/v1/system/status');
  }

  /**
   * Deep readiness diagnostic: GET /api/v1/system/readiness
   */
  async getReadiness(): Promise<SystemReadinessResponse> {
    return this.fetchWithTimeout<SystemReadinessResponse>('/api/v1/system/readiness');
  }

  /**
   * Runtime performance benchmarks: GET /api/v1/system/diagnostics
   */
  async getDiagnostics(): Promise<SystemDiagnosticsResponse> {
    return this.fetchWithTimeout<SystemDiagnosticsResponse>('/api/v1/system/diagnostics');
  }

  /**
   * Get operational data mode: GET /api/v1/digital-twin/mode
   */
  async getMode(): Promise<{ status: string; current_mode: OperationalMode; description: string }> {
    return this.fetchWithTimeout<{ status: string; current_mode: OperationalMode; description: string }>('/api/v1/digital-twin/mode');
  }

  /**
   * Set operational data mode: POST /api/v1/digital-twin/mode
   */
  async setMode(mode: OperationalMode): Promise<{ status: string; current_mode: OperationalMode; generated_alerts_count: number; timestamp: string }> {
    return this.fetchWithTimeout<{ status: string; current_mode: OperationalMode; generated_alerts_count: number; timestamp: string }>('/api/v1/digital-twin/mode', {
      method: 'POST',
      body: JSON.stringify({ mode }),
    });
  }

  /**
   * Complete Digital Twin State for 405 segments: GET /api/v1/digital-twin/state
   */
  async getDigitalTwinState(limit: number = 405): Promise<DigitalTwinStateResponse> {
    return this.fetchWithTimeout<DigitalTwinStateResponse>(`/api/v1/digital-twin/state?limit=${limit}`);
  }

  /**
   * Telemetry and state for a single segment: GET /api/v1/digital-twin/segment/{segment_id}
   */
  async getSegment(segmentId: string): Promise<SingleSegmentResponse> {
    return this.fetchWithTimeout<SingleSegmentResponse>(`/api/v1/digital-twin/segment/${encodeURIComponent(segmentId)}`);
  }

  /**
   * Active and acknowledged alerts: GET /api/v1/alerts/active
   */
  async getActiveAlerts(): Promise<AlertListResponse> {
    return this.fetchWithTimeout<AlertListResponse>('/api/v1/alerts/active');
  }

  /**
   * Complete alert history: GET /api/v1/alerts
   */
  async getAllAlerts(limit: number = 100): Promise<AlertListResponse> {
    return this.fetchWithTimeout<AlertListResponse>(`/api/v1/alerts?limit=${limit}`);
  }

  /**
   * Acknowledge an alert: POST /api/v1/alerts/{alert_id}/acknowledge
   */
  async acknowledgeAlert(alertId: string, operatorNote: string = ''): Promise<{ status: string; alert_id: string; message: string }> {
    return this.fetchWithTimeout<{ status: string; alert_id: string; message: string }>(`/api/v1/alerts/${encodeURIComponent(alertId)}/acknowledge`, {
      method: 'POST',
      body: JSON.stringify({ operator_note: operatorNote }),
    });
  }

  /**
   * VMS speed advisories & message displays: GET /api/v1/operations/vms
   */
  async getVMSAdvisories(): Promise<VMSResponse> {
    return this.fetchWithTimeout<VMSResponse>('/api/v1/operations/vms');
  }

  /**
   * Patrol unit tactical recommendations: GET /api/v1/operations/patrol
   */
  async getPatrolRecommendations(): Promise<PatrolResponse> {
    return this.fetchWithTimeout<PatrolResponse>('/api/v1/operations/patrol');
  }

  /**
   * Event timeline log: GET /api/v1/operations/timeline
   */
  async getTimeline(): Promise<TimelineResponse> {
    return this.fetchWithTimeout<TimelineResponse>('/api/v1/operations/timeline');
  }

  /**
   * SIH Demo Step execution: POST /api/v1/demo/step
   */
  async executeDemoStep(step: number): Promise<DemoStepResponse> {
    return this.fetchWithTimeout<DemoStepResponse>('/api/v1/demo/step', {
      method: 'POST',
      body: JSON.stringify({ step }),
    });
  }

  /**
   * SIH Demo Clean Reset: POST /api/v1/demo/reset
   */
  async resetDemo(): Promise<DemoResetResponse> {
    return this.fetchWithTimeout<DemoResetResponse>('/api/v1/demo/reset', {
      method: 'POST',
      body: JSON.stringify({}),
    });
  }

  /**
   * Trigger what-if incident simulation on a segment: POST /api/v1/simulation/incident
   */
  async simulateIncident(params: {
    segment_id: string;
    incident_type?: IncidentType;
    severity?: SeverityType;
    capacity_factor?: number;
    custom_speed_kph?: number;
  }): Promise<IncidentSimulationResponse> {
    return this.fetchWithTimeout<IncidentSimulationResponse>('/api/v1/simulation/incident', {
      method: 'POST',
      body: JSON.stringify({
        segment_id: params.segment_id,
        incident_type: params.incident_type || 'ACCIDENT',
        severity: params.severity || 'HIGH',
        capacity_factor: params.capacity_factor !== undefined ? params.capacity_factor : 0.20,
        custom_speed_kph: params.custom_speed_kph,
      }),
    });
  }

  /**
   * Compute baseline vs diversion route: POST /api/v1/routing/diversion
   */
  async computeDiversion(params: {
    origin_node: string;
    dest_node: string;
    incident_segment_id: string;
  }): Promise<DiversionRouteResponse> {
    return this.fetchWithTimeout<DiversionRouteResponse>('/api/v1/routing/diversion', {
      method: 'POST',
      body: JSON.stringify(params),
    });
  }

  /**
   * Dispatch closest emergency response depot: POST /api/v1/routing/emergency
   */
  async dispatchEmergency(params: {
    target_segment_id: string;
    incident_type?: IncidentType;
    severity?: SeverityType;
  }): Promise<EmergencyDispatchResponse> {
    return this.fetchWithTimeout<EmergencyDispatchResponse>('/api/v1/routing/emergency', {
      method: 'POST',
      body: JSON.stringify({
        target_segment_id: params.target_segment_id,
        incident_type: params.incident_type || 'ACCIDENT',
        severity: params.severity || 'HIGH',
      }),
    });
  }

  /**
   * Reset all simulated incidents: POST /api/v1/simulation/reset
   */
  async resetSimulation(): Promise<ResetSimulationResponse> {
    return this.fetchWithTimeout<ResetSimulationResponse>('/api/v1/simulation/reset', {
      method: 'POST',
      body: JSON.stringify({}),
    });
  }
}

export const api = new ApiClient(BASE_URL);
